            continue

        result[key] = value

    result["_source"] = "csv"
    result["_meta"] = {"file": os.path.basename("unknown"), "line": line_num}
    return result


def _try_numeric(value):
    """Try to convert a string to int or float."""
    try:
        if "." in value:
            return float(value)
        return int(value)
    except (ValueError, TypeError):
        return None


